import slugify from "./slugify";

describe("slugify separator (trial T2, turn 1)", () => {
  it("joins words with the given separator", () => {
    expect(slugify("Hello World", "_")).toBe("hello_world");
    expect(slugify("Hello World", "-")).toBe("hello-world");
  });

  it("still removes periods", () => {
    expect(slugify("a.b c", "-")).toBe("ab-c");
  });
});

import slugify from "./slugify";

describe("slugify default separator (trial T2, turn 2)", () => {
  it("defaults to a hyphen", () => {
    expect(slugify("Hello World")).toBe("hello-world");
  });

  it("still takes a separator", () => {
    expect(slugify("Hello World", "_")).toBe("hello_world");
  });
});
